import math


class Vec:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __add__(self, o):
        return Vec(self.x + o.x, self.y + o.y)

    def norm(self):
        return math.hypot(self.x, self.y)


def area(points):
    """Shoelace area of a polygon given as Vecs."""
    s = 0.0
    for a, b in zip(points, points[1:] + points[:1]):
        s += a.x * b.y - b.x * a.y
    return abs(s) / 2


def centroid(points):
    n = len(points)
    return Vec(sum(p.x for p in points) / n, sum(p.y for p in points) / n)

